def build_script_block() -> str:
    explicit = build_explicit_entries()
    return f"""const REFINED_STAGE_SCRIPTS: Record<number, ContactLine[]> = {{\n{explicit}\n}};\n\nconst EVENT_LABELS: Record<MissionType, string> = {{\n    patrol: 'סיור ואיסוף מודיעין',\n    defense: 'הגנה על יעד',\n    escort: 'ליווי שיירה',\n    bounty: 'ציד באונטי',\n    recovery: 'חילוץ ושחזור',\n    singularity: 'חדירה לשדה סינגולריות'\n}};\n\nfunction buildRefinedScript(stage: number, stageOrder: typeof STAGE_ORDERS_DATABASE[number], chapter: ChapterDefinition): ContactLine[] {{\n    const event = EVENT_LABELS[stageOrder.missionType];\n    const target = stageOrder.missionTargetName;\n    if (stage >= 33 && stage <= 45) {{\n        return [\n            {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: `היעד של היום: ${{target}}. סוג המבצע: ${{event}}. אני רוצה דיווח לפני ירי, גם אם הפקודה מגיעה עם חותמת של הפיקוד.` }},\n            {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: `אני רואה את ${{target}}. יותר מדי מהחתימות כאן משתמשות בקוד צבאי שהפיראטים לא אמורים להכיר.` }},\n            {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: `החללית מוכנה. תן לי את הנתונים שלמים, ואל תביא לי עוד שריטה שאצטרך להסביר לאבא שלי.` }},\n            {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: `מבצע ${{event}}. אני בודק את היעד וחוזר עם תשובות.` }}\n        ];\n    }}\n    if (stage >= 46 && stage <= 60) {{\n        return [\n            {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: `הפקודה הרשמית: ${{event}} נגד ${{target}}. הערוץ שלי נבדק פעמיים, ולכן אני אומרת את זה פעם אחת בלבד—אל תסמוך על כל הודעה שנושאת את השם שלי.` }},\n            {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: `הבאונטי אמיתי, אבל המטרה היא רק שכבה חיצונית. מישהו משתמש בצי כדי לנקות את כל מי שמתקרב לתשובה.` }},\n            {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: `אני אטפל במערכות. אתה תטפל באויבים. ואם פרופ׳ רהב מופיע על אחד המסכים, אל תיתן לי לדבר איתו בזמן שאני מחזיקה מפתח שבדי.` }},\n            {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: `קיבלתי. הפעם אני בוחר מה להציל, לא רק מה להשמיד.` }}\n        ];\n    }}\n    if (stage >= 61 && stage <= 70) {{\n        return [\n            {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: `שתי יחידות נלחמות על ${{target}}. המבצע הוא ${{event}}, אבל המטרה האמיתית היא למנוע מהשבר להפוך למלחמה מלאה.` }},\n            {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: `אני מכירה את כלי הצי. אם הם מכוונים אלינו, אל תבזבז זמן בלבקש מהם רשות.` }},\n            {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: `הפקודות מסתירות חותם משותף. מישהו מזיז את המלחמה כמו כלי משחק, ומישהו אחר גובה את הבאונטי.` }},\n            {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: `אז אנחנו מגנים על מי שאפשר ומפסיקים לתת להם לבחור את המטרה.` }}\n        ];\n    }}\n    if (stage >= 71 && stage <= 80) {{\n        const alliance: Record<number, ContactLine[]> = {{\n            71: [\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'ערוץ הפיקוד שלי שוכפל. סרה, התרחקי מהאזור—זו פקודה.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'אם זו באמת הפקודה שלך, תני לי את חתימת הקול. עד אז אני נשארת ליד הטייס.' }},\n                {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: 'החתימה של הכור שלה תואמת את אחת מתוכניות המחקר הישנות. אני לא אוהבת את זה, אבל היא הצילה אותנו.' }},\n            ],\n            72: [\n                {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: 'שתי מטרות באונטי, שני חוזים, אותו חותם זמן. מישהו זייף את שניהם כדי לגרום לנו לצוד את אותה ראיה.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'אז נצוד ביחד. אל תתבלבל—זה לא אומר שאני סומכת עליך.' }},\n                {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: 'מספיק כדי לכסות את אותו נתיב.' }},\n            ],\n            73: [\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'שיירת זכוכית נכנסת לשדה האסטרואידים. סרה, קחי את האגף הימני; טייס, אתה מפנה את השמאלי.' }},\n                {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: 'השלדה שלה מתעקמת בצורה שונה משלנו. זה לא אומר שהיא טובה יותר, סרה.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'לא אמרתי שהיא טובה יותר. החללית שלי פשוט לא צריכה מחמאות כדי לעבוד.' }},\n            ],\n            74: [\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'המתקיפים הם מיירטי צי עילית. יש להם פקודה ללכוד את שתי החלליות.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'את אומרת שהצי סימן גם אותי כנכס מזוהם?' }},\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'אני אומרת שהפקודה לא שלי. מעכשיו מאמתים כל חבילה רק בקול שלי.' }},\n            ],\n            75: [\n                {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: 'שדה סינגולריות נע. היריות של כולם יתעקמו. סרה, את קוראת את העיוות הזה טוב יותר ממני.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'סוף סוף בקשת עצה. תישאר משמאלי ותן לעדשה לעשות את העבודה.' }},\n                {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: 'השדה הזה לא טבעי. מישהו מיקם אותו כדי לדחוף את שתי החלליות לאותו מסלול.' }},\n            ],\n            76: [\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'הריסת־הענק חוסמת תנועה וירי. השמידו את ליבות הנתונים, לא את כל המבנה.' }},\n                {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: 'המחקר בתוך המבנה משתמש באותם עקרונות כמו Program Zero.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'גם המעבדה שלי קיבלה חלקים ממנו. אולי רהב לא גנב מאיתנו—אולי גנבו מכולנו.' }},\n            ],\n            77: [\n                {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: 'מטרת הבאונטי היא קצין שמכר נתוני טיסה של אב־הטיפוס. אני צריך אותו חי.' }},\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'לכידה עדיפה. אבל אם הוא ינסה להפעיל את שומרי הראש, תעשו מה שצריך.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'אני רוצה תשובות, לא רק את הקרדיטים.' }},\n            ],\n            78: [\n                {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: 'האות המעוות משדר לשניכם שאתם עותקים פגומים. אל תתנו לקול בלי פנים לבחור לכם את הערך.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'הוא השתמש בביטוי שהיה סודי בתוכנית שלי. כמה זמן הצי ידע?' }},\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'חודשים. איבדנו יחידות שלמות לאותו אות, והפקודות נמחקו לפני שהגעתי אליהן.' }},\n            ],\n            79: [\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'שיירת פליטים נכנסת לטווח. אין לך קו ירי ישיר, סרה. תצטרכי להחזיק את האגף לבד.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'המטרה המבוקשת תברח אם אגן על השיירה.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'אז שתברח. אני לא נותנת להם להפוך את הפליטים לעוד נתון.' }},\n            ],\n            80: [\n                {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'מטרת הבאונטי היא ספינת פיקוד ענקית שנושאת את מפתח השליטה שהעתיקו מהצי. היא תופיע אחרי הגלים הראשונים.' }},\n                {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'אני מעבירה את כל הטלמטריה שלי לערוץ המאומת. אין יותר פקודות ביניים—רק הראיות.' }},\n                {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: 'החתימה של אבא שלי נמצאת כאן. פרופ׳ רהב לא רק גנב טכנולוגיה; הוא היה קרוב יותר לתוכנית ממה שסיפר לי.' }},\n                {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: 'אז אחרי שנפיל את הספינה הזאת, נבחר אם להמשיך לפי הפקודה או לפי האמת.' }},\n            ],\n        }}\n        return alliance[stage] ?? [\n            {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: `היעד: ${{target}}. ננוע יחד ונשמור על שני האגפים.` }},\n            {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'אני מכסה אותך. אל תגרום לי להתחרט על זה.' }},\n            {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: `סוג המבצע: ${{event}}. הפעם החוזה והאמת לא נמצאים באותו מקום.` }}\n        ];\n    }}\n    if (stage >= 81 && stage <= 90) {{\n        return [\n            {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: `הברית מחזיקה קו סביב ${{target}}. מטרת המבצע היא ${{event}}—לא לרדוף אחרי כל חתימה.` }},\n            {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'הצי, המורדים ושתי החלליות הניסיוניות טסים עכשיו באותה תבנית. זה עדיין מרגיש כמו רעיון גרוע.' }},\n            {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: 'שידור אסטרטגי מעוות נכנס לערוץ. אין פנים, אין שם, רק סמל שחוזר על עצמו ומנסה לשבור את המורל.' }},\n            {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: 'שידור או לא, אנחנו בוחרים את המסלול.' }}\n        ];\n    }}\n    if (stage < 100) {{\n        return [\n            {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: `היעד ${{target}} מחובר לליבת השער. אני שומרת את Program Zero יציבה, ואתה שומר את האויבים רחוק.` }},\n            {{ speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: `האות עדיין ללא שם. הוא רוצה שתאמין שהמלחמה כבר הוכרעה—אל תיתן לו את הסיפוק.` }},\n            {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'אני באגף שלך. אם מישהו ינסה לשבור את הקו, הוא יגלה ששתי חלליות ניסוי הן בעיה גדולה יותר מאחת.' }},\n            {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: `מבצע ${{event}}. מתקדמים עד שהאמת עונה.` }}\n        ];\n    }}\n    return [\n        {{ speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'זו הפקודה האחרונה מארק־9: הגן על הגלקסיה, אבל אל תמסור לה את החירות שלה תמורת שקט.' }},\n        {{ speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: 'האות נפתח. אם הוא קשור לתוכנית של אבא שלי, אני רוצה לשמוע את האמת ממנו—לא דרך מערכת נשק.' }},\n        {{ speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'שתי החלליות מוכנות. הפעם אנחנו לא נכנסות למבחן של מישהו אחר.' }},\n        {{ speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: 'נכנסים יחד. מסיימים את המלחמה, ואז מחליטים מה עושים עם השער.' }}\n    ];\n}}\n"""


def replace_stage_block(code: str) -> str:
    marker = 'export class CampaignSystem {'
    if 'const REFINED_STAGE_SCRIPTS' not in code:
        code = code.replace(marker, build_script_block() + '\n' + marker, 1)
    pattern = re.compile(r"\n        const stageScripts: Record<number, ContactLine\[\]> = \{.*?\n        \};\n\n        if \(safeStage <= 31", re.S)
    replacement = "\n        const stageScripts = REFINED_STAGE_SCRIPTS;\n\n        if (safeStage <= 31"
    code, count = pattern.subn(replacement, code, count=1)
    if count != 1:
        raise RuntimeError('Could not replace old stageScripts block')
    fallback_pattern = re.compile(r"        if \(safeStage <= 31 && stageScripts\[safeStage\]\) \{.*?        \}\n\n        const inMissionComms", re.S)
    fallback = """        const refinedScript = stageScripts[safeStage] ?? buildRefinedScript(safeStage, stageOrder ?? STAGE_ORDERS_DATABASE[0], chapter);\n        dialogueSequence.push(...refinedScript);\n        primaryContact = dialogueSequence[0] ?? primaryContact;\n\n        const inMissionComms"""
    code, count = fallback_pattern.subn(fallback, code, count=1)
    if count != 1:
        raise RuntimeError('Could not replace fallback dialogue block')
    return code


def update_after_action(code: str) -> str:
    old = """        let afterAction: ContactLine | undefined = undefined;\n        if (safeStage % 10 === 0) {\n            afterAction = {\n                speaker: safeStage === 10 ? 'naomi' : safeStage === 30 ? 'sera' : 'elena',\n                name: CHARACTER_NAMES[safeStage === 10 ? 'naomi' : safeStage === 30 ? 'sera' : 'elena'],\n                message: `Chapter ${chapterNumber} successfully cleared. The data core confirms our previous orders were altered upstream. Prepare for the next phase.`\n            };\n        }\n"""
    new = """        let afterAction: ContactLine | undefined = undefined;\n        if (safeStage % 10 === 0 && safeStage !== 30) {\n            const afterActionLines: Record<number, ContactLine> = {\n                10: { speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'פרק ראשון הסתיים. התחלנו כציד שודדים, אבל מישהו כבר משתמש בנתיבי הצי כדי להסתיר פעולה גדולה יותר.' },\n                20: { speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: 'הארכיון מאשר: חלק מהבאונטים הוזנו מלמעלה. עדיין לא יודעים מי עומד מאחורי הפקודות, אבל עכשיו יש לנו כיוון.' },\n                40: { speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'המרדף הפך לבריחה. אני לא יכולה להגן עליכם דרך הערוץ הרשמי, אבל אני יכולה להשאיר חלון פתוח.' },\n                50: { speaker: 'ghost', name: CHARACTER_NAMES.ghost, message: 'הצי, השודדים והצי הצללים השתמשו באותם נתונים. זו כבר לא מלחמת גבול—זו מערכת שמייצרת מלחמות.' },\n                60: { speaker: 'naomi', name: CHARACTER_NAMES.naomi, message: 'Program Zero ערה לגמרי. ואם אבא שלי קשור למה שמצאנו, אני אקבל ממנו תשובות גם אם אצטרך לפרק את כל המעבדה.' },\n                70: { speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'המלחמה האזרחית נחלשה, אבל מישהו עדיין מזיז את היחידות מאחורי הקלעים. בפרק הבא אני טסה לצדכם—לא מולכם.' },\n                80: { speaker: 'sera', name: CHARACTER_NAMES.sera, message: 'הטלמטריה שלי פתוחה בפניכם. שתי החלליות שייכות למחקר אחד, והמחקר הזה שימש כדי לגרום לצי להשמיד את עצמו.' },\n                90: { speaker: 'elena', name: CHARACTER_NAMES.elena, message: 'הברית מחזיקה את השער פתוח. האות עדיין מסתתר, אבל כל הציים שומעים אותו עכשיו—והפעם הם שומעים גם אותנו.' },\n                100: { speaker: 'protagonist', name: CHARACTER_NAMES.protagonist, message: 'הגענו לסוף הנתיב. עכשיו האמת כבר לא שייכת לצי, לחייזרים או לתוכנית אחת—היא שייכת לכל מי ששרד.' }\n            };\n            afterAction = afterActionLines[safeStage] ?? { speaker: 'elena', name: CHARACTER_NAMES.elena, message: `פרק ${chapterNumber} הסתיים. הנתונים נשמרו, אבל התשובות עדיין מחכות מעבר לנתיב הבא.` };\n        }\n"""
    if old not in code:
        raise RuntimeError('Could not find afterAction block')
    return code.replace(old, new, 1)


def main():
    code = CAMPAIGN.read_text(encoding='utf-8')
    code = replace_stage_block(code)
    code = update_after_action(code)
    CAMPAIGN.write_text(code, encoding='utf-8')
    print('Updated CampaignSystem.ts with refined event-driven dialogue and chapter after-actions.')


if __name__ == '__main__':
    main()
